local CisternMaker = {}
local PRODUCTS = {
    simple_clay_cistern = { name = "Preprosta glinena cisterna", clayCost = 4, stoneCost = 2, time = 5, cost = 180, waterSupply = 35, happiness = 1, description = "Preprosta glinena cisterna za shranjevanje vode." },
    brick_lined_cistern = { name = "Opečnoobložena cisterna", brickCost = 3, clayCost = 2, stoneCost = 2, time = 8, cost = 440, waterSupply = 55, happiness = 2, prestige = 2, description = "Opečnoobložena cisterna za trgovce." },
    marble_cistern = { name = "Marmornata cisterna", marbleCost = 2, brickCost = 2, clayCost = 2, stoneCost = 2, time = 12, cost = 1000, waterSupply = 75, happiness = 2, prestige = 6, description = "Marmornata cisterna za plemiče." },
    silver_banded_cistern = { name = "Srebrnopasna cisterna", marbleCost = 2, silverCost = 1, brickCost = 2, clayCost = 2, stoneCost = 2, time = 16, cost = 2300, waterSupply = 95, happiness = 3, prestige = 14, description = "Srebrnopasna cisterna za visoke plemiče." },
    jewel_set_cistern = { name = "Draguljasta cisterna", marbleCost = 2, goldCost = 1, silverCost = 1, brickCost = 2, clayCost = 2, stoneCost = 2, jewelCost = 1, time = 20, cost = 4800, waterSupply = 120, happiness = 5, prestige = 27, description = "Cisterna z draguljem za visoko plemstvo." },
    royal_grand_cistern = { name = "Kraljevski veliki cisterna", marbleCost = 3, goldCost = 2, silverCost = 2, brickCost = 2, clayCost = 2, stoneCost = 2, jewelCost = 2, pearlCost = 2, time = 27, cost = 10000, waterSupply = 155, happiness = 12, prestige = 58, description = "Velika kraljevska cisterna z biseri in zlatom za kronanje." },
}
local BUILDINGS = {
    cistern_workshop = { name = "Cisternska delavnica", cost = { gold = 280, wood = 140, stone = 160, clay = 8 }, upkeep = 6, qualityBonus = 5 },
    waterworks_loft = { name = "Vodovodna podstrešje", cost = { gold = 1000, wood = 280, stone = 320, silver = 6, marble = 4 }, upkeep = 23, qualityBonus = 18 },
    master_cistern_atelier = { name = "Mojstrski cisterski atelje", cost = { gold = 2800, wood = 380, stone = 520, silver = 32, gold = 6 }, upkeep = 65, qualityBonus = 30 },
    royal_waterworks_palace = { name = "Kraljevska vodovodna palača", cost = { gold = 12000, wood = 600, stone = 800, gold = 80, jewel = 18 }, upkeep = 240, qualityBonus = 55, prestigeBonus = 50 },
}
CisternMaker.clayStock = 16; CisternMaker.stoneStock = 18; CisternMaker.brickStock = 12; CisternMaker.marbleStock = 10; CisternMaker.silverStock = 6; CisternMaker.goldStock = 6; CisternMaker.jewelStock = 4; CisternMaker.pearlStock = 4
CisternMaker.productStock = {}; CisternMaker.buildings = {}; CisternMaker.maker = nil; CisternMaker.activeMaking = {}; CisternMaker.totalProducts = 0; CisternMaker.dayTimer = 0
function CisternMaker.init() CisternMaker.clayStock=16; CisternMaker.stoneStock=18; CisternMaker.brickStock=12; CisternMaker.marbleStock=10; CisternMaker.silverStock=6; CisternMaker.goldStock=6; CisternMaker.jewelStock=4; CisternMaker.pearlStock=4; CisternMaker.productStock={}; CisternMaker.buildings={}; CisternMaker.maker=nil; CisternMaker.activeMaking={}; CisternMaker.totalProducts=0; CisternMaker.dayTimer=0; print("[CisternMaker] Royal Cistern Maker System initialized (6 products, 4 buildings)") end
function CisternMaker.hireMaker(n,s) s=s or math.random(55,90); local c=560+s*12; if not _G.state or (_G.state.gold or 0)<c then return false,"Premalo zlata" end; _G.state.gold=_G.state.gold-c; CisternMaker.maker={name=n or ("Cisternar "..math.random(1,99)),skill=s,hiredDay=os.time(),itemsMade=0}; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Cisternar najet: %s (spretnost: %d)",CisternMaker.maker.name,s),"success") end; return true end
function CisternMaker.canBuild(id) local d=BUILDINGS[id]; if not d then return false,"Neznana zgradba" end; if not _G.state then return false,"Brez stanja" end; if _G.state.gold<(d.cost.gold or 0) then return false,"Premalo zlata" end; if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" and (_G.state.resources[r] or 0)<a then return false,"Premalo "..r end end end; return true end
function CisternMaker.build(id) local ok,e=CisternMaker.canBuild(id); if not ok then return false,e end; local d=BUILDINGS[id]; _G.state.gold=_G.state.gold-(d.cost.gold or 0); if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" then _G.state.resources[r]=(_G.state.resources[r] or 0)-a end end end; table.insert(CisternMaker.buildings,{type=id,builtDay=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,"Zgrajeno: "..d.name,"success") end; return true end
function CisternMaker.getQualityBonus() local b=0; for _,bd in ipairs(CisternMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.qualityBonus then b=b+d.qualityBonus end end; return b end
function CisternMaker.canMake(pt) local d=PRODUCTS[pt]; if not d then return false,"Neznan produkt" end; if d.clayCost and CisternMaker.clayStock<(d.clayCost or 0) then return false,"Premalo gline" end; if d.stoneCost and CisternMaker.stoneStock<(d.stoneCost or 0) then return false,"Premalo kamna" end; if d.brickCost and CisternMaker.brickStock<(d.brickCost or 0) then return false,"Premalo opek" end; if d.marbleCost and CisternMaker.marbleStock<(d.marbleCost or 0) then return false,"Premalo marmorja" end; if d.silverCost and CisternMaker.silverStock<(d.silverCost or 0) then return false,"Premalo srebra" end; if d.goldCost and CisternMaker.goldStock<(d.goldCost or 0) then return false,"Premalo zlata" end; if d.jewelCost and CisternMaker.jewelStock<(d.jewelCost or 0) then return false,"Premalo draguljev" end; if d.pearlCost and CisternMaker.pearlStock<(d.pearlCost or 0) then return false,"Premalo biserov" end; if #CisternMaker.buildings==0 then return false,"Potrebna cisternska delavnica" end; if not CisternMaker.maker then return false,"Potreben cisternar" end; return true end
function CisternMaker.make(pt,qty) qty=qty or 1; local ok,e=CisternMaker.canMake(pt); if not ok then return false,e end; local d=PRODUCTS[pt]; if d.clayCost then CisternMaker.clayStock=CisternMaker.clayStock-d.clayCost*qty end; if d.stoneCost then CisternMaker.stoneStock=CisternMaker.stoneStock-d.stoneCost*qty end; if d.brickCost then CisternMaker.brickStock=CisternMaker.brickStock-d.brickCost*qty end; if d.marbleCost then CisternMaker.marbleStock=CisternMaker.marbleStock-d.marbleCost*qty end; if d.silverCost then CisternMaker.silverStock=CisternMaker.silverStock-d.silverCost*qty end; if d.goldCost then CisternMaker.goldStock=CisternMaker.goldStock-d.goldCost*qty end; if d.jewelCost then CisternMaker.jewelStock=CisternMaker.jewelStock-d.jewelCost*qty end; if d.pearlCost then CisternMaker.pearlStock=CisternMaker.pearlStock-d.pearlCost*qty end; local t=d.time; if CisternMaker.maker then t=math.max(1,t-math.floor(CisternMaker.maker.skill/13)) end; table.insert(CisternMaker.activeMaking,{id="cistern_"..tostring(os.time()).."_"..tostring(math.random(1000,9999)),productType=pt,productName=d.name,cost=d.cost*qty,quantity=qty,waterSupply=d.waterSupply or 0,prestige=d.prestige or 0,happiness=d.happiness or 0,daysRemaining=t,started=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Izdelava: %d %s (%d dni)",qty,d.name,t),"info") end; return true end
function CisternMaker.completeMaking(m) local q=1.0+(CisternMaker.getQualityBonus()/100); if CisternMaker.maker then q=q+(CisternMaker.maker.skill/140) end; q=math.min(2.5,q); CisternMaker.productStock[m.productType]=(CisternMaker.productStock[m.productType] or 0)+m.quantity; CisternMaker.totalProducts=CisternMaker.totalProducts+m.quantity; if m.waterSupply>0 and _G.state then _G.state.water=(_G.state.water or 0)+m.waterSupply end; if m.prestige>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.prestige) end; if m.happiness>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.happiness) end; if CisternMaker.maker then CisternMaker.maker.itemsMade=CisternMaker.maker.itemsMade+m.quantity; if math.random()<0.25 then CisternMaker.maker.skill=math.min(100,CisternMaker.maker.skill+1) end end; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Cisterna izdelana: %d %s (kakovost: %.1f)",m.quantity,m.productName,q),"success") end; if _G.GameEventBus then pcall(_G.GameEventBus.publish,"cistern.completed",{productName=m.productName,waterSupply=m.waterSupply,prestige=m.prestige,happiness=m.happiness}) end end
function CisternMaker.update(dt) if not _G.state then return end; CisternMaker.dayTimer=CisternMaker.dayTimer+dt; if CisternMaker.dayTimer>=30 then CisternMaker.dayTimer=0; for i=#CisternMaker.activeMaking,1,-1 do local m=CisternMaker.activeMaking[i]; m.daysRemaining=m.daysRemaining-1; if m.daysRemaining<=0 then CisternMaker.completeMaking(m); table.remove(CisternMaker.activeMaking,i) end end; local tu=0; for _,bd in ipairs(CisternMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.upkeep then tu=tu+d.upkeep end end; if CisternMaker.maker then tu=tu+15 end; if tu>0 and _G.state then _G.state.gold=math.max(0,(_G.state.gold or 0)-tu) end end end
function CisternMaker.getStats() return {clayStock=CisternMaker.clayStock,stoneStock=CisternMaker.stoneStock,brickStock=CisternMaker.brickStock,marbleStock=CisternMaker.marbleStock,silverStock=CisternMaker.silverStock,goldStock=CisternMaker.goldStock,jewelStock=CisternMaker.jewelStock,pearlStock=CisternMaker.pearlStock,productStock=CisternMaker.productStock,numBuildings=#CisternMaker.buildings,hasMaker=CisternMaker.maker~=nil,makerName=CisternMaker.maker and CisternMaker.maker.name or "—",makerSkill=CisternMaker.maker and CisternMaker.maker.skill or 0,activeMaking=#CisternMaker.activeMaking,totalProducts=CisternMaker.totalProducts} end
return CisternMaker
